},
["init"] = {
["custom"] = "aura_env.spinning = false\n\nlocal function doClick()\n    WeakAuras.ScanEvents(\"PSY_WHEEL_DECIDE_SPIN_GO\")\nend\n\nlocal f = PSY_WHEEL_DECIDE_BUTTON\nif not f then\n    f = CreateFrame(\"Button\", \"PSY_WHEEL_DECIDE_BUTTON\", aura_env.region, \"\")\nend\nf:SetAllPoints()\nf:RegisterForClicks(\"LeftButtonDown\",\"RightButtonDown\")\nf:SetScript(\"OnClick\", function()\n        doClick()\nend)\n\n\n",
["do_custom"] = true,
},
