["animate"] = false,
["customGrow"] = "(function()\n        local width = 400\n        local space = 2\n        return function(positions, activeRegions)\n            local y = 0\n            local count= math.max(#activeRegions, 1)\n            local regionWidth = (width - space * (count - 1)) / count\n            local x = (regionWidth - width) / 2\n            \n            for i, regionData in ipairs(activeRegions) do\n                regionData.region:SetRegionWidth(regionWidth)\n                positions[i] = {x, y}\n                x = x + regionWidth + space\n            end\n        end\nend)()",
