["init"] = {
["custom"] = "aura_env.keys = {}\n\naura_env.decide = function() \n    if #aura_env.keys == 0 then return math.random(1,5) end\n    \n    local selectedIndex = math.random(1, #aura_env.keys)\n    return selectedIndex\nend",
