},
["adjustedMax"] = "",
["adjustedMin"] = "",
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["cooldownSwipe"] = true,
["url"] = "https://wago.io/xzvpUDanJ/8",
["actions"] = {
["start"] = {
},
["init"] = {
["custom"] = "aura_env.spinning = false\naura_env.progress = 0\naura_env.count = 0\naura_env.winningIndex = 0\n\naura_env.getFakeData = function () \n    local keys = {}\n    keys[1] = aura_env.createKey(1, \"Psyder\", \"Algeth'ar Academy\", 25)\n    keys[2] = aura_env.createKey(2, \"Speef\", \"The Azure Vault\", 21)\n    keys[3] = aura_env.createKey(3, \"Mop\", \"Atal'Dazar\", 13)\n    keys[4] = aura_env.createKey(4, \"Grill\", \"Dawn of the Infinite: Galakrond's Fall\", 8)\n    keys[5] = aura_env.createKey(5, \"Psyala\", \"Throne of the Tides\", 4)\n    return keys\nend\n\naura_env.getStates = function(allStates, keys)\n    for i, key in pairs(allStates) do\n        allStates[i] = nil\n    end\n    for i, key in pairs(keys) do\n        allStates[i] = key\n    end\n    \n    aura_env.count = #allStates\nend\n\naura_env.createKey = function(id, player, keystone, difficulty) \n    local keystoneAbr = aura_env.abreviateKeyName(keystone)\n    local keystoneFull = aura_env.adjustKeyName(keystone)\n    return {\n        show = true,\n        changed = true,\n        autoHide = false,\n        progressType = \"static\",\n        name = \"keystone\"..id,\n        icon = 525134,\n        index = id,\n        player = ({strsplit(\"-\", player)})[1],\n        keystone = keystoneAbr,\n        keystoneFull = keystoneFull,\n        difficulty = difficulty,\n        tooltip = keystoneFull .. \" +\" .. difficulty\n    }\nend\n\naura_env.getManualAbrvs = function() \n    return {\n        [\"Dawn of the Infinite: Galakrond's Fall\"] = \"FALL\",\n        [\"Dawn of the Infinite: Murozond's Rise\"] = \"RISE\",   \n        [\"Uldaman: Legacy of Tyr\"] = \"ULD\",\n        [\"Neltharus\"] = \"NELT\",\n        [\"Algeth'ar Academy\"] = \"AA\",\n    }\nend\n\naura_env.abreviateKeyName = function(keystone)\n    local manual = aura_env.getManualAbrvs()[keystone]\n    if manual ~= nil then return manual end\n    \n    local keyname = string.gsub(keystone, \"%'\", \" \")\n    local replaced = \"\"\n    for i, word in pairs ({strsplit(\" \",keyname)}) do \n        if i == 1 and word == \"The\" then\n            replace = replaced\n        else\n            replaced = replaced .. string.sub(word, 1, 1) \n        end\n    end\n    return string.upper(replaced)\nend\n\naura_env.adjustKeyName = function(keystone)\n    local keystoneFull = keystone\n    keystoneFull =    string.gsub(keystoneFull, \"Dawn of the Infinite\", \"DOTI\")\n    return keystoneFull\nend",
["do_custom"] = true,
},
["finish"] = {
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "stateupdate",
["customVariables"] = "",
["event"] = "Health",
["unit"] = "player",
["subeventSuffix"] = "_CAST_START",
["subeventPrefix"] = "SPELL",
["events"] = "PSY_WHEEL_DECIDE_KEYS_OBTAINED PSY_WHEEL_DECIDE_SPIN_GO PSY_WHEEL_DECIDE_SPIN_STOP PSY_WHEEL_DECIDE_KEYS_DECIDED",
["names"] = {
},
["check"] = "event",
["spellIds"] = {
},
["custom"] = "function (allStates, e, arg1)\n    \n    if e == \"OPTIONS\" then\n        local keys = aura_env.getFakeData()\n        allStates = aura_env.getStates(allStates,keys)\n    end\n    \n    if e == \"PSY_WHEEL_DECIDE_KEYS_OBTAINED\" then\n        local keys = arg1\n        allStates = aura_env.getStates(allStates,keys)\n    end\n    \n    if e == \"PSY_WHEEL_DECIDE_SPIN_GO\" then\n        aura_env.winningIndex = 0\n        aura_env.spinning = true\n    end\n    \n    if e == \"PSY_WHEEL_DECIDE_SPIN_STOP\" then\n        aura_env.spinning = false\n    end\n    \n    if e == \"PSY_WHEEL_DECIDE_KEYS_DECIDED\" then\n        aura_env.winningIndex = arg1\n    end\n    \n    return true\nend",
["debuffType"] = "HELPFUL",
},
["untrigger"] = {
},
},
["activeTriggerMode"] = -10,
},
["frameStrata"] = 1,
["useTooltip"] = true,
["progressSource"] = {
-1,
"",
},
["animation"] = {
["start"] = {
["type"] = "none",
["easeStrength"] = 3,
["duration_type"] = "seconds",
["easeType"] = "none",
},
["main"] = {
["colorR"] = 1,
["scalex"] = 1,
["colorA"] = 1,
["use_rotate"] = true,
["duration_type"] = "seconds",
["rotateFunc"] = "function(progress, start, delta)\n    return start + (progress * delta)\nend\n",
["colorB"] = 1,
["alphaType"] = "straight",
["rotateType"] = "straight",
["colorG"] = 1,
["alphaFunc"] = "function(progress, start, delta)\n    return start + (progress * delta)\nend\n",
["duration"] = "1",
["use_color"] = false,
["use_translate"] = true,
["use_alpha"] = false,
["colorType"] = "straightColor",
["type"] = "custom",
["scaley"] = 1,
["easeType"] = "none",
["translateFunc"] = "function(progress, startX, startY, deltaX, deltaY)\n    local radius = 65\n    local radians = 2*math.pi\n    \n    \n    local chunks = aura_env.count\n    local chunkSize = radians / chunks\n    local angleOffset = (aura_env.state.index -1) * chunkSize\n    \n    \n    local angle = 0\n    if aura_env.spinning then\n        if aura_env.state.index == 1 then\n            aura_env.progress = progress\n        end\n    end\n    angle = aura_env.progress * radians\n    angle = angle + angleOffset\n    \n    local x = radius * math.cos(angle)\n    local y = -radius * math.sin(angle)\n    \n    if aura_env.winningIndex > 0 and aura_env.spinning then\n        \n        if aura_env.winningIndex == aura_env.state.index and (y >= -1 and y <= 1) and (x >= 0) then\n            aura_env.spinning = false\n            \n            local key = aura_env.state\n            WeakAuras.ScanEvents(\"PSY_WHEEL_DECIDE_SPIN_STOP\", key.player, key.keystoneFull, key.difficulty) \n            \n            if aura_env.config.announce and IsInGroup() then\n                SendChatMessage(\n                    \"**WHEEL-DECIDE** has spoken! \" .. key.keystone .. \" +\" .. key.difficulty .. \" (\" .. key.player .. \")\",\n                    \"PARTY\"\n                    \n                )\n            end\n        end\n        \n    end\n    \n    \n    return x,y\nend",
["preset"] = "orbit",
["alpha"] = 0,
["easeStrength"] = 3,
["y"] = 0,
["x"] = 0,
["scaleType"] = "straightScale",
["scaleFunc"] = "function(progress, startX, startY, scaleX, scaleY)\n    return startX + (progress * (scaleX - startX)), startY + (progress * (scaleY - startY))\nend\n",
["colorFunc"] = "function(progress, r1, g1, b1, a1, r2, g2, b2, a2)\n    return r1 + (progress * (r2 - r1)), g1 + (progress * (g2 - g1)), b1 + (progress * (b2 - b1)), a1 + (progress * (a2 - a1))\nend\n",
["rotate"] = -360,
