["names"] = {
},
["custom_type"] = "event",
["custom"] = "function (e)\n    \n    if e == \"PSY_WHEEL_DECIDE_SPIN_GO\" then\n        aura_env.soundHandle = select(2, PlaySound(aura_env.getSoundId(), \"Master\"))\n        return true    \n    end\n    \n    if e == \"PSY_WHEEL_DECIDE_SPIN_STOP\" then\n        if aura_env.soundHandle ~= -1 then\n            StopSound(aura_env.soundHandle)\n        end\n        return false\n    end\n    \n    return false\nend",
