["customText"] = "(function() \n    local function get(state, field)\n      return aura_env.states[state] and aura_env.states[state][field] or 0\n    end\n    return function()\n      local weathered = get(1, \"value\")\n      local carved = get(2, \"value\") + math.floor(weathered / 45) * 15\n      local runed = get(3, \"value\") + math.floor(carved / 45) * 15\n      local gilded = get(4, \"value\") + math.floor(runed / 45) * 15\n      return weathered, carved, runed, gilded\n    end\n    \nend)()",
