["init"] = {
["do_custom"] = true,
["custom"] = "\nlocal region = aura_env.region\n\nif not region.button then\n  region.button = CreateFrame(\"Button\", nil, aura_env.region, \"InsecureActionButtonTemplate\")\nend\n\nregion.button:SetAttribute(\"type\", \"spell\")\nregion.button:SetParent(region)\nregion.button:SetAllPoints()\nregion.button:SetAttribute(\"spell\", WeakAuras.GetData(aura_env.id).triggers[1].trigger.spellName)\nregion.button:RegisterForClicks(\"AnyUp\", \"AnyDown\")\n\n\naura_env.nodes = {\n  [414325] = true,\n  [414326] = true,\n  [414327] = true,\n  [414328] = true,\n  [414329] = true,\n  [414330] = true,\n  [414331] = true,\n  [414332] = true,\n  [414335] = true,\n  [414336] = true,\n  [414337] = true,\n  [414338] = true,\n  [414339] = true,\n  [423363] = true,\n  [423364] = true,\n  [423366] = true,\n  [423367] = true,\n  [423368] = true,\n  [454006] = true,\n  [454008] = true,\n  [454050] = true,\n  [454053] = true,\n  [454064] = true,\n  [454066] = true,\n  [454067] = true,\n  [454069] = true,\n  [454072] = true,\n  [454074] = true,\n  [454077] = true,\n  [454079] = true,\n  [454082] = true,\n  [454084] = true,\n}\n\n\n\n\n",
