["colorFunc"] = "function(progress, r1, g1, b1, a1, r2, g2, b2, a2)\n    local palletteChoice = aura_env.config and aura_env.config.colorChoice or 1\n    local smoothColors = aura_env.config and aura_env.config.smoothColors\n    \n    local pallette = aura_env.colors[palletteChoice]\n    \n    if WeakAuras.IsOptionsOpen() then\n        --Do default code when open\n        if smoothColors then\n            local progress4 = min(progress * 5 + 1, 5)\n            local colorProgress = progress4 % 1\n            local colorChoice = floor(progress4)\n            r1, g1, b1 = unpack(pallette[colorChoice])\n            r2, g2, b2 = unpack(pallette[min(colorChoice + 1, 5)])\n            return WeakAuras.GetHSVTransition(colorProgress, r1, g1, b1, 1, r2, g2, b2, 1)\n        else\n            local colorChoice = floor(min(progress * 5 + 1, 5))\n            return unpack(pallette[colorChoice])\n        end\n    else\n        --Do normal code when the options is not open.\n        local percent = aura_env.state.perc\n        local colorChoice, colorProgress\n        if     percent <= .015 then\n            colorChoice = 1\n            colorProgress = (percent - .015)/.015\n        elseif percent <= .03 then\n            colorChoice = 2\n            colorProgress = (percent - .03)/.02\n        elseif percent <= .05 then\n            colorChoice = 3\n            colorProgress = (percent - .05)/.05\n        elseif percent <= .1 then\n            colorChoice = 4\n        else\n            return unpack(pallette[5])\n        end\n        if not smoothColors then\n            return unpack(pallette[colorChoice])\n        else\n            \n            r1, g1, b1 = unpack(pallette[colorChoice])\n            r2, g2, b2 = unpack(pallette[colorChoice + 1])\n            return WeakAuras.GetHSVTransition(colorProgress, r1, g1, b1, 1, r2, g2, b2, 1)\n        end\n    end\n    return 1,1,1\nend",
